# V SPARK 2026 - Problem 1: Array Frequency Peak (Python)
import sys
from collections import Counter

def solve(input_str):
    nums = list(map(int, input_str.strip().split()))
    counts = Counter(nums)
    # Highest frequency first, then smallest value
    sorted_items = sorted(counts.items(), key=lambda x: (-x[1], x[0]))
    return str(sorted_items[0][0])

if __name__ == '__main__':
    data = sys.stdin.read()
    if data.strip():
        print(solve(data))

