# V SPARK 2026 - Problem 2: Valid Campus Token (Python)
import sys

def solve(s):
    s = s.strip()
    stack = []
    pairs = {')': '(', '}': '{', ']': '['}
    for char in s:
        if char in '({[':
            stack.append(char)
        elif char in pairs:
            if not stack or stack.pop() != pairs[char]:
                return 'INVALID'
    return 'VALID' if not stack else 'INVALID'

if __name__ == '__main__':
    inp = sys.stdin.read().strip()
    if inp:
        print(solve(inp))

